import json
print(open("arch.json").read()[:500])
def silu(x): return x/(1+np.exp(-x))
def fwd(W, X):
    h=silu(X@W["l1.weight"].T+W["l1.bias"]); h=silu(h@W["l2.weight"].T+W["l2.bias"]); return h@W["l3.weight"].T+W["l3.bias"]
def inp(s):
    A,B=np.meshgrid(np.arange(32),np.arange(32),indexing="ij"); A=A.ravel();B=B.ravel()
    X=np.zeros((1024,68)); X[np.arange(1024),A]=1; X[np.arange(1024),32+B]=1; X[:,64+s]=1; return X
W={n:load(n) for n in NAMES}
for s in range(4):
    lg=fwd(W,inp(s)); p=lg.argmax(1).reshape(32,32)
    pr=np.exp(lg-lg.max(1,keepdims=True)); pr=pr/pr.sum(1,keepdims=True)
    print("skill",s,"classes",np.bincount(p.ravel(),minlength=63)[:12], "mean conf %.3f"%pr.max(1).mean(), "frac conf<.6 %.3f"%(pr.max(1)<.6).mean())
    for r in p[:32]: print("".join("%x"%v if v<16 else "*" for v in r))
